function parse(frame) {
  const toBytes = (input) => {
    if (Array.isArray(input)) return input.map((value) => Number(value) & 0xFF);
    if (typeof Uint8Array !== 'undefined' && input instanceof Uint8Array) return Array.from(input);
    if (input && input.buffer instanceof ArrayBuffer) {
      return Array.from(new Uint8Array(input.buffer, input.byteOffset || 0, input.byteLength));
    }
    const clean = String(input || '').replace(/0x/gi, '').replace(/[^0-9a-f]/gi, '');
    if (!clean || clean.length % 2 !== 0) return [];
    const out = [];
    for (let i = 0; i < clean.length; i += 2) out.push(parseInt(clean.slice(i, i + 2), 16));
    return out;
  };

  const readInt = (bytes, offset, size, signed, endian) => {
    let value = 0;
    if (endian === 'LE') {
      for (let i = 0; i < size; i += 1) value += (bytes[offset + i] || 0) * Math.pow(2, 8 * i);
    } else {
      for (let i = 0; i < size; i += 1) value = value * 256 + (bytes[offset + i] || 0);
    }
    if (signed) {
      const sign = Math.pow(2, size * 8 - 1);
      const full = Math.pow(2, size * 8);
      if (value >= sign) value -= full;
    }
    return value;
  };

  const hex = (bytes, offset, length) => bytes
    .slice(offset, offset + length)
    .map((value) => value.toString(16).padStart(2, '0').toUpperCase())
    .join(' ');

  const series = (bytes, offset, count, size, signed, endian, convert) => {
    const buffer = [];
    for (let i = 0; i < count; i += 1) {
      const raw = readInt(bytes, offset + i * size, size, signed, endian);
      buffer.push(convert ? convert(raw, i) : raw);
    }
    return { buffer, value: buffer.length ? buffer[buffer.length - 1] : 0, raw: hex(bytes, offset, count * size) };
  };

  const scalar = (bytes, index, title, offset, size, signed, endian, convert) => {
    const rawValue = readInt(bytes, offset, size, signed, endian);
    return {
      index,
      title,
      value: convert ? convert(rawValue) : rawValue,
      raw: hex(bytes, offset, size)
    };
  };

  const pt100Temperature = (raw) => {
    const A = 3.9083e-3;
    const B = -5.775e-7;
    const r0 = 100;
    const resistance = Math.abs(raw) * 0.0002980232;
    const d = A * A - 4 * B * (1 - resistance / r0);
    return d < 0 ? NaN : (-A + Math.sqrt(d)) / (2 * B);
  };

  const parseBearing = (bytes) => {
    const vibration = series(bytes, 12, 2132, 2, true, 'LE', (raw) => raw * 0.000488);
    const strain1 = series(bytes, 4276, 160, 3, true, 'BE', (raw) => raw * 2.5 / 8388608.0);
    const strain2 = series(bytes, 4756, 160, 3, true, 'BE', (raw) => raw * 2.5 / 8388608.0);
    const strain3 = series(bytes, 5236, 160, 3, true, 'BE', (raw) => raw * 2.5 / 8388608.0);
    return {
      title: '轴承 ID 0x01',
      hardwareId: 1,
      datasets: [
        { index: 0, title: '轴承-振动', units: 'g', sampleRate: 5300, ...vibration },
        { index: 1, title: '轴承-应变1', units: 'V', ...strain1 },
        { index: 2, title: '轴承-应变2', units: 'V', ...strain2 },
        { index: 3, title: '轴承-应变3', units: 'V', ...strain3 },
        scalar(bytes, 4, '轴承-PT100 ADC', 5716, 3, true, 'BE', (raw) => raw * 2.5 / 8388608.0),
        scalar(bytes, 5, '轴承-TEMP117', 5719, 2, false, 'BE', (raw) => raw * 0.0078125)
      ]
    };
  };

  const parseBush = (bytes) => {
    const strain1 = series(bytes, 12, 160, 3, true, 'BE', (raw) => raw * 2.5 / 8388608.0);
    const strain2 = series(bytes, 492, 160, 3, true, 'BE', (raw) => raw * 2.5 / 8388608.0);
    const strain3 = series(bytes, 972, 160, 3, true, 'BE', (raw) => raw * 2.5 / 8388608.0);
    return {
      title: '轴瓦 ID 0x02',
      hardwareId: 2,
      datasets: [
        { index: 6, title: '轴瓦-应变1', units: 'V', ...strain1 },
        { index: 7, title: '轴瓦-应变2', units: 'V', ...strain2 },
        { index: 8, title: '轴瓦-应变3', units: 'V', ...strain3 },
        scalar(bytes, 9, '轴瓦-PT100温度', 1452, 3, true, 'BE', pt100Temperature),
        scalar(bytes, 10, '轴瓦-TMP117', 1455, 2, false, 'LE', (raw) => raw * 0.0078125)
      ]
    };
  };

